#include <bits/stdc++.h>
using namespace std;

const int maxn = 5050;
const int mod = 1000000007;

int n, a[maxn], fac[maxn], C[maxn][maxn], b[maxn], d[maxn][maxn];
bool vis[maxn];

void solve() {
	cin >> n;
	for (int i = 0; i <= n; ++i) {
		vis[i] = 0;
		for (int j = 0; j <= n; ++j) {
			d[i][j] = 0;
		}
	}
	fac[0] = 1;
	for (int i = 1; i <= n; ++i) {
		cin >> a[i];
		fac[i] = 1LL * fac[i - 1] * i % mod;
		b[i] = b[i - 1] + (a[i] == -1);
		if (a[i] != -1) {
			vis[a[i]] = 1;
		}
	}
	for (int i = 0; i <= n; ++i) {
		C[i][0] = C[i][i] = 1;
		for (int j = 1; j < i; ++j) {
			C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % mod;
		}
	}
	int mn1 = n;
	for (int i = 1; i <= n; ++i) {
		int mn2 = n;
		for (int j = n; j >= i; --j) {
			int x = b[j] - b[i - 1], y = min(mn1, mn2);
			++d[x][0];
			--d[x][y];
			if (a[j] != -1) {
				mn2 = min(mn2, a[j]);
			}
		}
		if (a[i] != -1) {
			mn1 = min(mn1, a[i]);
		}
	}
	for (int i = 0; i <= b[n]; ++i) {
		for (int j = 1; j <= n; ++j) {
			d[i][j] += d[i][j - 1];
		}
	}
	int ans = 0, cnt = 0;
	for (int i = 0; i < n; ++i) {
		cnt += (!vis[i]);
		for (int j = cnt; j <= b[n]; ++j) {
			ans = (ans + 1LL * C[j][cnt] * fac[cnt] % mod * fac[b[n] - cnt] % mod * d[j][i]) % mod;
		}
	}
	cout << ans << '\n';
}

int main() {
	int T;
	cin >> T;
	while (T--) {
		solve();
	}
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int maxn = 500100;

int n, a[maxn], b[maxn], c[maxn], p[maxn], q[maxn];

struct node {
	int r, x;
	node(int a = 0, int b = 0) : r(a), x(b) {}
};

inline bool operator < (const node &a, const node &b) {
	return a.r > b.r || (a.r == b.r && a.x > b.x);
}

vector<node> vc[maxn];

struct DS1 {
	int c[maxn];

	inline void init() {
		for (int i = 0; i <= n; ++i) {
			c[i] = 0;
		}
	}

	inline void update(int x, int d) {
		for (int i = x; i <= n; i += (i & (-i))) {
			c[i] = max(c[i], d);
		}
	}

	inline int query(int x) {
		int res = 0;
		for (int i = x; i; i -= (i & (-i))) {
			res = max(res, c[i]);
		}
		return res;
	}
} T1;

struct DS2 {
	int c[maxn];

	inline void init() {
		for (int i = 0; i <= n; ++i) {
			c[i] = n + 1;
		}
	}

	inline void update(int x, int d) {
		for (int i = x; i; i -= (i & (-i))) {
			c[i] = min(c[i], d);
		}
	}

	inline int query(int x) {
		int res = n + 1;
		for (int i = x; i <= n; i += (i & (-i))) {
			res = min(res, c[i]);
		}
		return res;
	}
} T2;

void solve() {
	cin >> n;
	for (int i = 1; i <= n; ++i) {
		cin >> a[i];
		p[a[i]] = i;
		q[i] = 0;
		vector<node>().swap(vc[i]);
	}
	for (int i = 1; i <= n; ++i) {
		cin >> b[i];
		if (b[i]) {
			q[b[i]] = i;
		}
	}
	T1.init();
	for (int i = 1; i <= n; ++i) {
		if (q[i]) {
			if (T1.query(p[i]) > q[i]) {
				cout << "-1\n";
				return;
			}
			T1.update(p[i], q[i]);
		}
	}
	T1.init();
	T2.init();
	for (int i = 1; i <= n; ++i) {
		if (q[a[i]]) {
			T1.update(a[i], q[a[i]]);
		} else {
			c[i] = T1.query(a[i]) + 1;
		}
	}
	for (int i = n; i; --i) {
		if (q[a[i]]) {
			T2.update(a[i], q[a[i]]);
		} else {
			int r = T2.query(a[i]) - 1;
			if (c[i] > r) {
				cout << "-1\n";
				return;
			}
			vc[c[i]].emplace_back(r, a[i]);
		}
	}
	priority_queue<node> pq;
	for (int i = 1; i <= n; ++i) {
		for (node u : vc[i]) {
			pq.push(u);
		}
		if (!b[i]) {
			if (pq.empty() || pq.top().r < i) {
				cout << "-1\n";
				return;
			}
			b[i] = pq.top().x;
			pq.pop();
		}
	}
	for (int i = 1; i <= n; ++i) {
		cout << b[i] << " \n"[i == n];
	}
}

int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
	int T;
	cin >> T;
	while (T--) {
		solve();
	}
	return 0;
}

