#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int maxn = 500100;

int n, a[maxn];
mt19937 rnd(chrono::steady_clock::now().time_since_epoch().count());

int p[maxn], nt, ls[maxn], rs[maxn], sz[maxn];
bool vis[maxn];

struct vec {
	ll a0, a1, a2;
	vec(ll a = 0, ll b = 0, ll c = 0) : a0(a), a1(b), a2(c) {}
} val[maxn];

struct mat {
	ll a00, a01, a02, a10, a11, a12, a20, a21, a22;
	mat(ll a = 0, ll b = 0, ll c = 0, ll d = 0, ll e = 0, ll f = 0, ll g = 0, ll h = 0, ll i = 0) : a00(a), a01(b), a02(c), a10(d), a11(e), a12(f), a20(g), a21(h), a22(i) {}
} I, tag[maxn];

inline vec operator * (const vec &a, const mat &b) {
	vec res;
	res.a0 = a.a0 * b.a00 + a.a1 * b.a10 + a.a2 * b.a20;
	res.a1 = a.a0 * b.a01 + a.a1 * b.a11 + a.a2 * b.a21;
	res.a2 = a.a0 * b.a02 + a.a1 * b.a12 + a.a2 * b.a22;
	return res;
}

inline mat operator * (const mat &a, const mat &b) {
	mat res;
	res.a00 = a.a00 * b.a00 + a.a01 * b.a10 + a.a02 * b.a20;
	res.a01 = a.a00 * b.a01 + a.a01 * b.a11 + a.a02 * b.a21;
	res.a02 = a.a00 * b.a02 + a.a01 * b.a12 + a.a02 * b.a22;
	res.a10 = a.a10 * b.a00 + a.a11 * b.a10 + a.a12 * b.a20;
	res.a11 = a.a10 * b.a01 + a.a11 * b.a11 + a.a12 * b.a21;
	res.a12 = a.a10 * b.a02 + a.a11 * b.a12 + a.a12 * b.a22;
	res.a20 = a.a20 * b.a00 + a.a21 * b.a10 + a.a22 * b.a20;
	res.a21 = a.a20 * b.a01 + a.a21 * b.a11 + a.a22 * b.a21;
	res.a22 = a.a20 * b.a02 + a.a21 * b.a12 + a.a22 * b.a22;
	return res;
}

inline void init() {
	for (int i = 0; i <= nt; ++i) {
		p[i] = ls[i] = rs[i] = sz[i] = 0;
		val[i] = vec();
		tag[i] = I;
		vis[i] = 0;
	}
	nt = 0;
}

inline int newnode(ll x, ll y) {
	int u = ++nt;
	p[u] = rnd();
	ls[u] = rs[u] = 0;
	sz[u] = 1;
	val[u] = vec(x, y, 1);
	tag[u] = I;
	vis[u] = 0;
	return u;
}

inline void pushup(int x) {
	sz[x] = sz[ls[x]] + sz[rs[x]] + 1;
}

inline void pushtag(int x, const mat &y) {
	if (!x) {
		return;
	}
	val[x] = val[x] * y;
	tag[x] = tag[x] * y;
	vis[x] = 1;
}

inline void pushdown(int x) {
	if (!vis[x]) {
		return;
	}
	pushtag(ls[x], tag[x]);
	pushtag(rs[x], tag[x]);
	vis[x] = 0;
	tag[x] = I;
}

void split(int u, int &x, int &y) {
	if (!u) {
		x = y = 0;
		return;
	}
	pushdown(u);
	if (val[u].a0 < 0) {
		x = u;
		split(rs[u], rs[u], y);
	} else {
		y = u;
		split(ls[u], x, ls[u]);
	}
	pushup(u);
}

int merge(int x, int y) {
	if (!x || !y) {
		return x | y;
	}
	pushdown(x);
	pushdown(y);
	if (p[x] < p[y]) {
		rs[x] = merge(rs[x], y);
		pushup(x);
		return x;
	} else {
		ls[y] = merge(x, ls[y]);
		pushup(y);
		return y;
	}
}

ll f[maxn], tot;

void dfs(int u) {
	if (!u) {
		return;
	}
	pushdown(u);
	dfs(ls[u]);
	f[++tot] = val[u].a0;
	dfs(rs[u]);
}

void solve() {
	cin >> n;
	for (int i = 1; i <= n; ++i) {
		a[i] = -1;
	}
	for (int i = 1, x; i <= n; ++i) {
		cin >> x;
		if (x) {
			a[x] = (i & 1);
		}
	}
	init();
	int rt = 0;
	ll l = 0, r = 0, x = 0;
	if (a[1] == 1) {
		l = r = 1;
	} else if (a[1] == -1) {
		rt = newnode(0, 1);
		r = 1;
	}
	for (ll i = 1; i < n; ++i) {
		x += l * l * 2 + (-i - i - (n & 1)) * l + i * ((n + 1) / 2);
		pushtag(rt, mat(1, 0, 0, 4, 1, 0, -i - i - (n & 1) - 2, 0, 1));
		if (a[i + 1] == 1) {
			pushtag(rt, mat(1, 0, 0, 0, 1, 0, 0, 1, 1));
			++l;
			++r;
		} else if (a[i + 1] == -1) {
			int u, v;
			split(rt, u, v);
			pushtag(v, mat(1, 0, 0, 0, 1, 0, 0, 1, 1));
			rt = merge(merge(u, newnode(0, l + 1 + sz[u])), v);
			++r;
		}
	}
	tot = 0;
	dfs(rt);
	ll ans = -x;
	for (int i = 1; i <= (n + 1) / 2 - l; ++i) {
		ans -= f[i];
	}
	for (ll i = 1; i <= n; ++i) {
		ans += i * i;
	}
	cout << ans << '\n';
}

int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
	I.a00 = I.a11 = I.a22 = 1;
	int T;
	cin >> T;
	while (T--) {
		solve();
	}
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int maxn = 2000100;
const ll mod = 1000000007;

int n, a[maxn], m, nxt[maxn], stk[maxn], top;
ll f[maxn], d[maxn];
char s[maxn];

inline ll calc() {
	top = 0;
	for (int i = m; i >= 1; i -= 2) {
		while (top && a[stk[top]] - stk[top] / 2 < a[i] - i / 2) {
			--top;
		}
		nxt[i] = stk[top];
		stk[++top] = i;
	}
	top = 0;
	for (int i = m - 1; i >= 1; i -= 2) {
		while (top && a[stk[top]] - stk[top] / 2 < a[i] - i / 2) {
			--top;
		}
		nxt[i] = stk[top];
		stk[++top] = i;
	}
	for (int i = 1; i < m; ++i) {
		f[i] = d[i] = 0;
	}
	f[1] = a[1];
	for (int i = 3; i < m; i += 2) {
		f[i] = 1;
	}
	ll ans = 0;
	for (int i = 1; i < m; ++i) {
		if (i >= 3) {
			d[i] = (d[i] + d[i - 2]) % mod;
		}
		f[i] = (f[i] + d[i]) % mod;
		int j = i + 1, x = 0;
		while (j < m) {
			int k = (nxt[j] ? nxt[j] : m);
			f[j] = (f[j] + f[i] * (a[j] - x)) % mod;
			x = a[j] + (k - j) / 2 - 1;
			d[j + 2] = (d[j + 2] + f[i]) % mod;
			d[k] = (d[k] - f[i] + mod) % mod;
			j = k;
		}
		if ((m - i) & 1) {
			ans = (ans + f[i]) % mod;
		}
	}
	return ans * a[m] % mod;
}

void solve() {
	cin >> n >> s;
	m = 0;
	for (int i = 0, j = 0; i < n; i = (++j)) {
		while (j + 1 < n && s[j + 1] == s[i]) {
			++j;
		}
		a[++m] = j - i + 1;
	}
	if (m == 1) {
		cout << n - 1 << '\n';
		return;
	}
	if (m == 2) {
		cout << 1LL * a[1] * a[2] % mod << '\n';
		return;
	}
	ll ans = calc();
	--m;
	for (int i = 1; i <= m; ++i) {
		a[i] = a[i + 1];
	}
	a[1] = 1;
	ans = (ans + calc()) % mod;
	cout << ans << '\n';
}

int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
	int T;
	cin >> T;
	while (T--) {
		solve();
	}
	return 0;
}

